import base64
import json
import os
from typing import Any, Dict, Optional

import requests


GOOGLE_KMS_URL = "https://cloudkms.googleapis.com/v1"


def _access_token() -> str:
    token = os.environ.get("GOOGLE_OAUTH_ACCESS_TOKEN")
    if token:
        return token
    raise RuntimeError("GOOGLE_OAUTH_ACCESS_TOKEN is required")


def decrypt_payload(ciphertext_b64: str, key_name: str, aad_b64: Optional[str] = None) -> bytes:
    url = f"{GOOGLE_KMS_URL}/{key_name}:decrypt"
    payload: Dict[str, Any] = {"ciphertext": ciphertext_b64}
    if aad_b64 is not None:
        payload["additionalAuthenticatedData"] = aad_b64
    headers = {
        "Authorization": f"Bearer {_access_token()}",
        "Content-Type": "application/json",
    }
    response = requests.post(url, headers=headers, json=payload, timeout=30)
    response.raise_for_status()
    data = response.json()
    plaintext_b64 = data["plaintext"]
    return base64.b64decode(plaintext_b64)


def main() -> None:
    ciphertext_b64 = os.environ.get("CIPHERTEXT_B64")
    key_name = os.environ.get("GOOGLE_KMS_KEY_NAME")
    aad_b64 = os.environ.get("AAD_B64")
    if not ciphertext_b64 or not key_name:
        raise RuntimeError("CIPHERTEXT_B64 and GOOGLE_KMS_KEY_NAME are required")
    plaintext = decrypt_payload(ciphertext_b64, key_name, aad_b64)
    os.write(1, plaintext)


if __name__ == "__main__":
    main()

import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


@dataclass
class EnvelopeCiphertext:
    encrypted_data_key: str
    nonce: str
    ciphertext: str
    kms_key_id: str


class EnvelopeEncryptionError(Exception):
    pass


class KmsEnvelopeEncryptor:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None) -> None:
        self.kms_key_id = kms_key_id
        self.kms_client = boto3.client("kms", region_name=region_name or os.getenv("AWS_REGION"))

    def encrypt(self, plaintext: bytes, encryption_context: Optional[Dict[str, str]] = None) -> EnvelopeCiphertext:
        try:
            data_key_resp = self.kms_client.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_key = data_key_resp["Plaintext"]
            encrypted_key = data_key_resp["CiphertextBlob"]
            aesgcm = AESGCM(plaintext_key)
            nonce = os.urandom(12)
            ciphertext = aesgcm.encrypt(nonce, plaintext, None)
            return EnvelopeCiphertext(
                encrypted_data_key=base64.b64encode(encrypted_key).decode("utf-8"),
                nonce=base64.b64encode(nonce).decode("utf-8"),
                ciphertext=base64.b64encode(ciphertext).decode("utf-8"),
                kms_key_id=self.kms_key_id,
            )
        except (BotoCoreError, ClientError) as exc:
            raise EnvelopeEncryptionError(str(exc)) from exc

    def decrypt(self, envelope: EnvelopeCiphertext, encryption_context: Optional[Dict[str, str]] = None) -> bytes:
        try:
            encrypted_key = base64.b64decode(envelope.encrypted_data_key)
            nonce = base64.b64decode(envelope.nonce)
            ciphertext = base64.b64decode(envelope.ciphertext)
            data_key_resp = self.kms_client.decrypt(
                CiphertextBlob=encrypted_key,
                EncryptionContext=encryption_context or {},
            )
            plaintext_key = data_key_resp["Plaintext"]
            aesgcm = AESGCM(plaintext_key)
            return aesgcm.decrypt(nonce, ciphertext, None)
        except (BotoCoreError, ClientError, ValueError) as exc:
            raise EnvelopeEncryptionError(str(exc)) from exc


def encrypt_text(text: str, kms_key_id: str, region_name: Optional[str] = None) -> str:
    encryptor = KmsEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name)
    envelope = encryptor.encrypt(text.encode("utf-8"))
    return json.dumps(envelope.__dict__)


def decrypt_text(envelope_json: str, kms_key_id: str, region_name: Optional[str] = None) -> str:
    encryptor = KmsEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name)
    envelope_data: Dict[str, Any] = json.loads(envelope_json)
    envelope = EnvelopeCiphertext(**envelope_data)
    return encryptor.decrypt(envelope).decode("utf-8")

import base64
import json
import os
from typing import Any, Dict, Optional

import requests


GOOGLE_KMS_URL = "https://cloudkms.googleapis.com/v1"


def _access_token() -> str:
    token = os.environ.get("GOOGLE_OAUTH_ACCESS_TOKEN")
    if token:
        return token
    raise RuntimeError("GOOGLE_OAUTH_ACCESS_TOKEN is required")


def _request(method: str, url: str, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    headers = {
        "Authorization": f"Bearer {_access_token()}",
        "Content-Type": "application/json",
    }
    response = requests.request(method, url, headers=headers, json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def sign_payload(message: bytes, key_name: str) -> str:
    url = f"{GOOGLE_KMS_URL}/{key_name}:asymmetricSign"
    digest = base64.b64encode(message).decode("ascii")
    response = _request("POST", url, {"digest": {"sha256": digest}})
    return response["signature"]


def verify_signature(message: bytes, signature_b64: str, public_key_name: str) -> bool:
    url = f"{GOOGLE_KMS_URL}/{public_key_name}:verify"
    digest = base64.b64encode(message).decode("ascii")
    response = _request("POST", url, {"digest": {"sha256": digest}, "signature": signature_b64})
    return bool(response.get("name")) or response.get("success", False)


def main() -> None:
    mode = os.environ.get("MODE", "sign")
    key_name = os.environ.get("GOOGLE_KMS_KEY_NAME")
    if not key_name:
        raise RuntimeError("GOOGLE_KMS_KEY_NAME is required")
    message = os.environ.get("MESSAGE", "").encode("utf-8")
    if mode == "sign":
        os.write(1, sign_payload(message, key_name).encode("utf-8"))
        return
    signature_b64 = os.environ.get("SIGNATURE_B64")
    if not signature_b64:
        raise RuntimeError("SIGNATURE_B64 is required for verify mode")
    os.write(1, json.dumps({"verified": verify_signature(message, signature_b64, key_name)}).encode("utf-8"))


if __name__ == "__main__":
    main()

